        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الْكِيمِيَاءُ الْأَكْبَرُ الزِّرَاعَةُ.", "translation": "امام صادق (علیه‌السلام) فرمودند: کشاورزی، بزرگ‌ترین کیمیاگری است.", "source": "الكافي، جلد ۵، صفحه ۲۶۱"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّ اللَّهَ جَعَلَ أَرْزَاقَ أَنْبِيَائِهِ فِي الزَّرْعِ وَ الضَّرْعِ لِكَيْلَا يَكْرَهُوا شَيْئاً مِنْ قَطْرِ السَّمَاءِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: خداوند روزی پیامبران خود را در کشاورزی و دامداری قرار داد، تا بارش‌های آسمان را ناخوش ندارند.", "source": "الكافي، جلد ۵، صفحه ۲۶۰"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ وَجَدَ مَاءً وَ تُرَاباً ثُمَّ افْتَقَرَ فَأَبْعَدَهُ اللَّهُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر که با وجود داشتن آب و خاک نیازمند باشد، خداوند او را از رحمت خود دور می‌گرداند.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۶۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): اُطْلُبُوا الرِّزْقَ فِي خَبَايَا الْأَرْضِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: رزق و روزی خود را از ژرفای زمین جستجو کنید (یعنی کشاورزی کنید).", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۴۱"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): خُلِقَ لِلْإِنْسَانِ الشَّجَرُ فَكُلِّفَ غَرْسَهَا وَ سَقْيَهَا وَ الْقِيَامَ عَلَيْهَا.", "translation": "امام صادق (علیه‌السلام) فرمودند: درخت برای انسان آفریده شد، پس او مکلف گردید به کاشتن، آب دادن و مواظبت نمودن از آن.", "source": "بحار الأنوار، جلد ۳، صفحه ۸۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ سَقَى طَلْحَةً أَوْ سِدْرَةً فَكَأَنَّمَا سَقَى مُؤْمِناً ظَمْآنَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر کس درخت طلح یا سدری را آب دهد، گویا مؤمن تشنه‌ای را سیراب نموده است.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۴۳"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): خَيْرُ الْأَعْمَالِ الْحَرْثُ.", "translation": "امام باقر (علیه‌السلام) فرمودند: بهترین کارها کشاورزی است.", "source": "الكافي، جلد ۵، صفحه ۲۶۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): لَا تَبِيعُوا ضِيَاعَكُمْ وَ مِيَاهَكُمْ إِلَّا أَنْ تَشْتَرُوا بِهَا مِثْلَهَا.", "translation": "امام صادق (علیه‌السلام) فرمودند: زمین‌های کشاورزی و چاه‌های آب خود را نفروشید مگر آنکه با بهای آن، زمین یا آبی مانند آن بخرید.", "source": "الكافي، جلد ۵، صفحه ۹۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): عَلَيْكُمْ بِالْغَنَمِ وَ الْحَرْثِ فَإِنَّهُمَا يَرُوحَانِ بِخَيْرٍ وَ يَغْدُوَانِ بِخَيْرٍ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: بر شما باد دامداری و کشاورزی؛ زیرا این دو پیوسته شب و روز با خود خیر به همراه دارند.", "source": "الخصال، صفحه ۴۵"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنْ أَحْيَا أَرْضاً مَوَاتاً فَهِيَ لَهُ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس زمین مرده‌ای را زنده و آباد کند، آن زمین از آنِ اوست.", "source": "الكافي، جلد ۵، صفحه ۲۷۹"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): عَمَارَةُ الْبُلْدَانِ بِالزِّرَاعَةِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: آبادانی شهرها به واسطه کشاورزی است.", "source": "غرر الحكم، صفحه ۲۹۸"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَكْرِمُوا الْخُبْزَ فَإِنَّ اللَّهَ تَبَارَكَ وَ تَعَالَى أَنْزَلَ لَهُ بَرَكَاتِ السَّمَاءِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: نان را که فرآورده کشاورزی است عزیز دارید، چه آنکه خداوند برکات آسمان را برای آن فرستاده است.", "source": "الكافي، جلد ۶، صفحه ۳۰۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): خَيْرُ الْمَالِ سِكَّةٌ مَأْبُورَةٌ وَ مُهْرَةٌ مَأْمُورَةٌ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: بهترین مال، درختان خرمای گرده‌افشانی شده (زراعت) و دام‌های زایا است.", "source": "الكافي، جلد ۵، صفحه ۲۶۰"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْساً أَوْ يَزْرَعُ زَرْعاً فَيَأْكُلُ مِنْهُ إِنْسَانٌ أَوْ طَيْرٌ أَوْ بَهِيمَةٌ إِلَّا كَانَتْ لَهُ بِهِ صَدَقَةٌ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر مسلمانی که درختی بکارد یا زراعتی انجام دهد و پرنده یا انسان یا حیوانی از آن بخورد، تا روز قیامت برای او صدقه نوشته می‌شود.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۴۶۰"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): لَوْ أَنَّ السَّاعَةَ قَامَتْ وَ فِي يَدِ أَحَدِكُمْ فَسِيلَةٌ فَلْيَغْرِسْهَا.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: اگر قیامت برپا شود و در دست یکی از شما نهال خرمایی باشد، باید آن را بکارد.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۴۶۰"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ بَنَى بُنْيَاناً أَوْ غَرَسَ غَرْساً فِي غَيْرِ ظُلْمٍ كَانَ لَهُ أَجْرٌ جَارٍ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر کس بنایی بسازد یا درختی بکارد بدون آنکه ظلمی کند، پاداشی پیوسته و جاری خواهد داشت.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۴۶۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): شِرَاءُ الضِّيَاعِ بَرَكَةٌ.", "translation": "امام صادق (علیه‌السلام) فرمودند: خریدن زمین‌های کشاورزی و آباد کردن آن‌ها مایه برکت است.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۴۲"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الثَّمَرَةُ مِنَ الشَّجَرَةِ كَالْوَلَدِ مِنَ الرَّجُلِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: میوه برای درخت، همانند فرزند برای انسان است (کنایه از زایش و تداوم حیات).", "source": "غرر الحكم، صفحه ۲۹۹"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): لَمَّا هَبَطَ آدَمُ (علیه‌السلام) مِنَ الْجَنَّةِ أَمَرَهُ اللَّهُ بِالْحَرْثِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: هنگامی که آدم (علیه‌السلام) از بهشت فرود آمد، خداوند او را به کشاورزی فرمان داد.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۴۶۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): ثَلَاثَةٌ تَخْرِقُ الْحُجُبَ... وَ صَوْتُ أَقْلَامِ الْعُلَمَاءِ وَ خُطَى الْمُجَاهِدِينَ وَ صَوْتُ مَغَازِلِ الْمُحْصَنَاتِ وَ مَسَاحِي الزَّارِعِينَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: صدای بیل کشاورزان از جمله صداهایی است که حجاب‌ها را پاره کرده و به درگاه الهی می‌رسد.", "source": "جامع الأخبار، صفحه ۳۹۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الزِّرَاعَةُ مَفَاتِيحُ الرِّزْقِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: کشاورزی، کلیدهای روزی است.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۴۶۱"},
        {"text": "قَالَ عَلِيُّ بْنُ الْحُسَيْنِ (علیه‌السلام): إِنِّي لَأُحِبُّ أَنْ أَرَى الرَّجُلَ يَحْرُثُ لِعِيَالِهِ.", "translation": "امام سجاد (علیه‌السلام) فرمودند: من دوست دارم مردی را ببینم که برای تأمین معاش خانواده‌اش کشاورزی می‌کند.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۶۶"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ لَمْ يَبْنِ أَرْضَهُ خَرِبَتْ وَ أَهْلَكَ مَالَهُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: کسی که زمین خود را آباد نکند، ویران می‌گردد و دارایی‌اش تباه می‌شود.", "source": "غرر الحكم، صفحه ۳۵۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّ اللَّهَ أَعْطَانَا الْأَرْضَ لِنَعْمُرَهَا.", "translation": "امام صادق (علیه‌السلام) فرمودند: همانا خداوند زمین را به ما ارزانی داشت تا آن را آباد سازیم.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۴۲"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَا زَرَعَ الزَّارِعُونَ زَرْعاً إِلَّا رَزَقَهُمُ اللَّهُ حَظّاً مِنْهُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: کشاورزان هیچ کشتی نکردند مگر آنکه خداوند بهره‌ای از آن به ایشان روزی داد.", "source": "بحار الأنوار، جلد ۱۰۰، صفحه ۶۵"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنْ نَصَبَ شَجَرَةً وَ صَبَرَ عَلَى رِعَايَتِهَا حَتَّى تُثْمِرَ كَانَ لَهُ فِي كُلِّ شَيْءٍ يُصَابُ مِنْ ثَمَرَتِهَا صَدَقَةٌ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس درختی بکارد و در نگهداری آن شکیبایی ورزد تا به بار بنشیند، هر چه از آن میوه به دست آید نزد خدا برایش صدقه است.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۴۶۱"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): النَّخْلَةُ شَجَرَةٌ مُبَارَكَةٌ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: نخل، درختی خجسته و پربرکت است.", "source": "بحار الأنوار، جلد ۶۳، صفحه ۱۱۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): الْعِبَادَةُ سَبْعُونَ جُزْءاً أَفْضَلُهَا طَلَبُ الْحَلَالِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: عبادت هفتاد بخش است که برترین آن‌ها طلب روزی حلال است.", "source": "الكافي، جلد ۵، صفحه ۷۸"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): طَلَبُ الْحَلَالِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ وَ مُسْلِمَةٍ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: کار کردن برای کسب مال حلال، بر هر مرد و زن مسلمان واجب است.", "source": "جامع الأخبار، صفحه ۳۸۹"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ بَاتَ كَالًّا مِنْ طَلَبِ الْحَلَالِ بَاتَ مَغْفُوراً لَهُ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: کسی که به دنبال روزی حلال، روز خود را خسته سپری کند، آمرزیده شب را به صبح می‌رساند.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): الْعِبَادَةُ عَشَرَةُ أَجْزَاءٍ تِسْعَةٌ مِنْهَا فِي طَلَبِ الْحَلَالِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: عبادت ده جزء است که نُه جزء آن در کار و تلاش برای به دست آوردن روزی حلال است.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۱۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): كَدُّ الْمَرْءِ عَلَى عِيَالِهِ مِنْ حَلَالٍ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: اجر کسی که برای تأمین خانواده‌اش از راه حلال زحمت می‌کشد، مانند مجاهد در راه خداست.", "source": "الكافي، جلد ۵، صفحه ۸۸"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): تَرْكُ لُقْمَةِ حَرَامٍ أَحَبُّ إِلَى اللَّهِ مِنْ صَلَاةِ أَلْفَيْ رَكْعَةٍ تَطَوُّعاً.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: رها کردن یک لقمه حرام، پیش خدا از دو هزار رکعت نماز مستحبی محبوب‌تر است.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۲۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): طُوبَى لِمَنْ طَابَ كَسْبُهُ وَ صَلُحَتْ سَرِيرَتُهُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: خوشا به حال کسی که کسب او پاکیزه (حلال) و باطنش نیکو باشد.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): لَا تَدَعْ طَلَبَ الرِّزْقِ مِنْ حِلِّهِ فَإِنَّهُ عَوْنٌ لَكَ عَلَى دِينِكَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: تلاش در به دست آوردن روزی حلال را رها مساز، زیرا که آن کمک‌کار دین‌داری توست.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۵"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): تَرْكُ التِّجَارَةِ يَنْقُصُ الْعَقْلَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: رها کردن کسب و تجارت، عقل انسان را کاهش می‌دهد.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۱۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): يَا مَعْشَرَ التُّجَّارِ الْفِقْهَ ثُمَّ الْمَتْجَرَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: ای گروه تاجران! ابتدا احکام شرعی را یاد بگیرید، سپس تجارت کنید.", "source": "الكافي، جلد ۵، صفحه ۱۵۰"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ طَلَبَ الدُّنْيَا حَلَالًا فِي عَفَافٍ كَانَ فِي دَرَجَةِ الشُّهَدَاءِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: کسی که دنیای خود را با عفت نفس و از راه حلال تأمین می‌کند، مقام شهیدان را دارد.", "source": "المحجة البيضاء، جلد ۳، صفحه ۲۰۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): عَلَيْكَ بِلُزُومِ الْحَلَالِ وَ حُسْنِ الْبِرِّ بِالْعِيَالِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: بر تو باد که روزی را از راه حلال به دست آوری و با خانواده به نیکی رفتار کنی.", "source": "غرر الحكم، صفحه ۷۹"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ لَمْ يَسْتَحِي مِنْ طَلَبِ الْحَلَالِ خَفَّتْ مَئُونَتُهُ وَ نَعِمَ عِيَالُهُ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: کسی که از تحصیل روزی حلال شرم نکند، مخارجش سبک و خانواده‌اش در نعمت خواهند بود.", "source": "تحف العقول، صفحه ۵۷"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَطِبْ كَسْبَكَ تُسْتَجَبْ دَعْوَتُكَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: درآمدت را پاک و حلال کن تا دعایت مستجاب شود.", "source": "بحار الأنوار، جلد ۹۳، صفحه ۳۵۸"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنِ اتَّجَرَ بِغَيْرِ فِقْهٍ تَوَرَّطَ فِي الشُّبُهَاتِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس بدون یادگیری احکام فقهی تجارت کند، در گرداب شبهات و حرام گرفتار می‌شود.", "source": "الكافي، جلد ۵، صفحه ۱۵۰"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): تَرْكُ الْقَبِيحِ مِنَ الْكَسْبِ أَعْظَمُ جِهَادٍ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: رها کردن کسب و کار ناپسند و حرام، بزرگ‌ترین جهاد است.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۲۴"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ اللَّهَ يُحِبُّ أَنْ يَرَى عَبْدَهُ تَعِباً فِي طَلَبِ الْحَلَالِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: خداوند دوست دارد بنده خود را در جستجوی روزی حلال خسته و تلاشگر ببیند.", "source": "كنز العمال، جلد ۶، صفحه ۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): رَغِيفٌ حَلَالٌ خَيْرٌ مِنْ مَائِدَةِ حَرَامٍ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: یک تکه نان حلال، از سفره‌ای رنگین اما حرام بهتر است.", "source": "غرر الحكم، صفحه ۱۴۶"},
        {"text": "قَالَ عَلِيُّ بْنُ الْحُسَيْنِ (علیه‌السلام): أَطْيَبُ الْمَكَاسِبِ عَمَلُ الرَّجُلِ بِيَدِهِ.", "translation": "امام سجاد (علیه‌السلام) فرمودند: پاکیزه‌ترین درآمدها، دسترنج کار خود انسان است.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۲۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّمَا السَّعَادَةُ فِي الْكَسْبِ الْحَلَالِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: براستی که سعادت و خوشبختی در کسب حلال نهفته است.", "source": "بحار الأنوار، جلد ۱۰۰، صفحه ۶۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَفْضَلُ الْكَسْبِ بَيْعٌ مَبْرُورٌ وَ عَمَلُ الرَّجُلِ بِيَدِهِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: برترین کسب، معامله پاک و کار کردن انسان با دست خویش است.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۲۴"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): لَيْسَ شَيْءٌ أَفْضَلَ عِنْدَ اللَّهِ مِنْ أَنْ يُسْأَلَ مِنْ فَضْلِهِ الْحَلَالِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: چیزی نزد خدا برتر از آن نیست که از فضل حلال او درخواست روزی شود.", "source": "الكافي، جلد ۲، صفحه ۴۶۶"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ أَكَلَ الْحَلَالَ صَفَا قَلْبُهُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس روزی حلال بخورد، قلبش صفا و نورانیت می‌یابد.", "source": "غرر الحكم، صفحه ۳۵۴"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): الرِّزْقُ الْحَلَالُ مِنْ أَكْبَرِ النِّعَمِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: روزی حلال از بزرگ‌ترین نعمت‌های الهی است.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۱۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): خَيْرُ الرِّزْقِ مَا يَكْفِي.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: بهترین روزی آن است که برای زندگی کفایت کند.", "source": "الأمالي للصدوق، صفحه ۳۹۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ أَكَلَ مِنْ كَدِّ يَدِهِ حَلَالًا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر کس از دسترنج حلال خود بخورد، درهای بهشت به رویش گشوده می‌شود.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۲۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): اللَّهُمَّ ارْزُقْنِي رِزْقاً حَلَالًا طَيِّباً وَاسِعاً.", "translation": "امام صادق (علیه‌السلام) فرمودند: پروردگارا، روزی حلال، پاکیزه و وسیع به من عطا فرما.", "source": "تهذيب الأحكام، جلد ۳، صفحه ۷۷"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): الْكَسْبُ الْحَلَالُ يُنِيرُ الْقَلْبَ.", "translation": "امام باقر (علیه‌السلام) فرمودند: کسب حلال، دل را روشن و نورانی می‌کند.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۹"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّ اللَّهَ تَعَالَى يُحِبُّ الْمُحْتَرِفَ الْأَمِينَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: خداوند متعال کاسب و پیشه‌ور امین را دوست دارد.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۲۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَا مِنْ حَرَكَةٍ إِلَّا وَ أَنْتَ مُحْتَاجٌ فِيهَا إِلَى مَعْرِفَةٍ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: در هیچ حرکتی و کسبی نیستی مگر اینکه در آن نیازمند شناخت احکام دین هستی.", "source": "تحف العقول، صفحه ۱۷۱"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): لَا خَيْرَ فِي مَالٍ لَا يُزَكَّى وَ لَا يُؤَدَّى حَقُّهُ.", "translation": "امام صادق (علیه‌السلام) فرمودند: خیری در مالی نیست که زکات آن داده نشود و حق دیگران از آن پرداخت نگردد.", "source": "الكافي، جلد ۳، صفحه ۵۰۲"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الظُّلْمُ ثَلَاثَةٌ: ظُلْمٌ لَا يَغْفِرُهُ اللَّهُ، وَ ظُلْمٌ يَغْفِرُهُ، وَ ظُلْمٌ لَا يَدَعُهُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: ظلم سه گونه است: ظلمی که خدا نمی‌آمرزد (شرک)، ظلمی که می‌آمرزد (ظلم به خود) و ظلمی که رها نمی‌کند (حق‌الناس).", "source": "نهج البلاغة، خطبه ۱۷۶"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ غَشَّ مُسْلِماً فِي شَرِيدَةٍ أَوْ بَيْعٍ فَلَيْسَ مِنَّا.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر کس با مسلمانی در معامله فریبکاری کند، از ما نیست.", "source": "من لا يحضره الفقيه، جلد ۳، صفحه ۱۶۰"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): إِيَّاكُمْ وَ دَعْوَةَ الْمَظْلُومِ فَإِنَّهَا تُرْفَعُ فَوْقَ السَّمَاءِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: از دعای ستمدیده بپرهیزید که همانا از آسمان‌ها فراتر می‌رود.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۳۵۹"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): أَدُّوا حُقُوقَ النَّاسِ إِلَيْهِمْ قَبْلَ أَنْ يَأْتِيَ يَوْمٌ لَا دِرْهَمَ فِيهِ وَ لَا دِينَارَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: حقوق مردم را به آنان بازگردانید پیش از آنکه روزی فرا رسد که در آن نه درهمی است و نه دیناری.", "source": "وسائل الشيعة، جلد ۱۲، صفحه ۲۸۴"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ ظَلَمَ أَجِيراً أُجْرَتَهُ أَحْبَطَ اللَّهُ عَمَلَهُ وَ حَرَّمَ عَلَيْهِ رِيحَ الْجَنَّةِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر کس در مزد کارگر ستم کند، خداوند عملش را تباه و بوی بهشت را بر او حرام می‌کند.", "source": "الأمالي للصدوق، صفحه ۴۳۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّ اللَّهَ لَا يَقْبَلُ صَلَاةَ مَنْ فِي ذِمَّتِهِ حَقٌّ لِأَخِيهِ الْمُسْلِمِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: خداوند نماز کسی را که حق برادر مسلمانش بر گردن او باشد، نمی‌پذیرد.", "source": "مستدرك الوسائل، جلد ۱۲، صفحه ۹۸"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): أَعْظَمُ الذُّنُوبِ عِنْدَ اللَّهِ تَعَالَى غَصْبُ حَقِّ الْمُسْلِمِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: بزرگ‌ترین گناهان نزد خداوند، غصب کردن حق یک مسلمان است.", "source": "غرر الحكم، صفحه ۲۳۱"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): مَنْ بَخَسَ النَّاسَ حُقُوقَهُمْ فَهُوَ مَحْرُومٌ مِنْ فَضْلِ اللَّهِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: هر کس از حقوق مردم کم بگذارد، از فضل خدا محروم است.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۳۸۲"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الْعَدْلُ أَسَاسُ الْمُلْكِ وَ فِيهِ صَلَاحُ الرَّعِيَّةِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: عدالت شالوده حکومت است و اصلاح مردم در آن است.", "source": "غرر الحكم، صفحه ۱۱۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَخْوَفُ مَا أَخَافُ عَلَى أُمَّتِي ظُلْمُ النَّاسِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: ترسناک‌ترین چیزی که بر امتم بیم دارم، ستم به مردم و تضییع حقوق آنان است.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۳۳۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الدَّيْنُ هَمٌّ بِاللَّيْلِ وَ ذُلٌّ بِالنَّهَارِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: بدهی و حق‌الناس، غصه شب و خواری روز است.", "source": "الكافي، جلد ۵، صفحه ۹۳"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَطْلُ الْغَنِيِّ ظُلْمٌ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: تأخیر توانگر در پرداخت حق دیگران، ستم است.", "source": "من لا يحضره الفقيه، جلد ۳، صفحه ۱۸"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): أَدِّ الْحَقَّ إِلَى مَنْ ائْتَمَنَكَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: حق کسی را که به تو اعتماد کرده است، بپرداز.", "source": "غرر الحكم، صفحه ۱۴۶"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): ثَلَاثَةٌ لَا عُذْرَ لِأَحَدٍ فِيهَا: أَدَاءُ الْأَمَانَةِ، وَ الْوَفَاءُ بِالْعَهْدِ، وَ بِرُّ الْوَالِدَيْنِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: در سه چیز برای هیچ‌کس عذری پذیرفته نیست: ادای امانت، وفای به عهد و نیکی به والدین.", "source": "الكافي، جلد ۲، صفحه ۱۶۲"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): بِئْسَ الزَّادُ إِلَى الْمَعَادِ الْعُدْوَانُ عَلَى الْعِبَادِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: بدترین توشه برای آخرت، تجاوز به حقوق بندگان است.", "source": "نهج البلاغة، حکمت ۲۲۱"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): إِنَّ اللَّهَ يَنْتَقِمُ مِنَ الظَّالِمِ فِي الدُّنْيَا وَ الْآخِرَةِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: خداوند از پایمال‌کننده حقوق دیگران در دنیا و آخرت انتقام می‌گیرد.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۳۳۱"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): حُرْمَةُ مَالِ الْمُسْلِمِ كَحُرْمَةِ دَمِهِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: حرمت مال مسلمان همچون حرمت خون اوست.", "source": "مستدرك الوسائل، جلد ۱۲، صفحه ۹۸"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنْ مَنَعَ قِيرَاطاً مِنْ زَكَاةِ مَالِهِ فَلَيْسَ بِمُؤْمِنٍ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس از پرداخت قیرطی از حقوق واجب مالش خودداری کند، مؤمن نیست.", "source": "الكافي، جلد ۳، صفحه ۵۰۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ ضَيَّعَ الْحُقُوقَ ضَيَّعَهُ اللَّهُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس حقوق دیگران را ضایع کند، خداوند او را ضایع می‌گرداند.", "source": "غرر الحكم، صفحه ۳۷۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ عُقُوقُ النَّاسِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: ترسناک‌ترین چیزی که بر شما می‌ترسم، پایمال کردن حقوق مردم است.", "source": "مستدرك الوسائل، جلد ۱۲، صفحه ۱۰۲"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): مَا مِنْ ظُلْمٍ أَعْظَمَ مِنْ أَنْ يَأْخُذَ الرَّجُلُ حَقَّ أَخِيهِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: هیچ ستمی بزرگ‌تر از آن نیست که انسان حق برادر مسلمانش را بگیرد.", "source": "الكافي، جلد ۲، صفحه ۳۳۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنْ أَكَلَ مَالَ أَخِيهِ ظُلْماً فَقَدْ حَارَبَ اللَّهَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس مال برادرش را به ستم و ناحق بخورد، به جنگ با خدا برخاسته است.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۳۰۷"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): إِنَّ لِلَّهِ فِي عِبَادِهِ حُقُوقاً.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: همانا خداوند را در میان بندگانش حقوقی است که باید به یکدیگر بپردازند.", "source": "نهج البلاغة، حکمت ۳۲۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِيَّاكُمْ وَ الشُّحَّ فَإِنَّهُ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: از بخل و ندادن حق مردم بپرهیزید، که پیشینیان شما را هلاک کرد.", "source": "بحار الأنوار، جلد ۷۰، صفحه ۳۰۱"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَ لَا يَخْذُلُهُ.", "translation": "امام صادق (علیه‌السلام) فرمودند: مسلمان برادر مسلمان است؛ نه به او ستم می‌کند و نه حقوقش را بی‌پاسخ می‌گذارد.", "source": "الكافي، جلد ۲، صفحه ۱۶۶"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): يُعْرَفُ إِيمَانُ الرَّجُلِ بِأَدَاءِ حُقُوقِ الْإِخْوَانِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: ایمان انسان با ادای حقوق برادران دینی‌اش شناخته می‌شود.", "source": "غرر الحكم، صفحه ۳۷۲"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): كُلُّ ذَنْبٍ يُكَفِّرُهُ اللَّهُ إِلَّا حُقُوقَ الْعِبَادِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: خداوند هر گناهی را ممکن است بیامرزد، مگر حقوق پایمال‌شده بندگان را.", "source": "وسائل الشيعة، جلد ۱۶، صفحه ۴۴"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ أَنْ يَسْتَطِيلَ الْمَرْءُ فِي عِرْضِ مُسْلِمٍ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: از بزرگ‌ترین گناهان این است که انسان به آبروی مسلمانی (حق‌الناس معنوی) دست‌درازی کند.", "source": "مستدرك الوسائل، جلد ۹، صفحه ۱۱۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ حَاسَبَ نَفْسَهُ رَبِحَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس در ادای حقوق مردم از خود حساب بکشد، سود می‌برد.", "source": "غرر الحكم، صفحه ۲۳۶"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): لَا تَنْظُرُوا إِلَى طُولِ رُكُوعِ الرَّجُلِ وَ سُجُودِهِ وَ لَكِنِ انْظُرُوا إِلَى صِدْقِ حَدِيثِهِ وَ أَدَاءِ أَمَانَتِهِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: به طول رکوع و سجود فرد ننگرید، بلکه به راست‌گویی و امانت‌داری او توجه کنید.", "source": "الكافي، جلد ۲، صفحه ۱۰۴"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): أَدُّوا الْأَمَانَةَ وَ لَوْ إِلَى قَاتِلِ الْحُسَيْنِ بْنِ عَلِيٍّ.", "translation": "امام باقر (علیه‌السلام) فرمودند: امانت را برگردانید، حتی اگر امانت‌دهنده قاتل حسین بن علی (علیهماالسلام) باشد.", "source": "وسائل الشيعة، جلد ۱۹، صفحه ۷۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّ اللَّهَ لَمْ يَبْعَثْ نَبِيّاً إِلَّا بِصِدْقِ الْحَدِيثِ وَ أَدَاءِ الْأَمَانَةِ إِلَى الْبَرِّ وَ الْفَاجِرِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: خداوند هیچ پیامبری را مبعوث نکرد مگر به راست‌گویی و ادای امانت به نیکوکار و بدکار.", "source": "الكافي، جلد ۲، صفحه ۱۰۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الْأَمَانَةُ تَجُرُّ الرِّزْقَ وَ الْخِيَانَةُ تَجُرُّ الْفَقْرَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: امانت‌داری مایه جلب روزی است و خیانت در امانت فقر می‌آورد.", "source": "تحف العقول، صفحه ۲۲۱"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): لَيْسَ مِنَّا مَنْ خَانَ مُسْلِماً فِي أَهْلِهِ وَ لَا مَالِهِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: از ما نیست کسی که به مسلمانی در خانواده یا مال او خیانت ورزد.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۱۷۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): شِيعَتُنَا أَهْلُ الْوَفَاءِ وَ الْأَمَانَةِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: شیعیان ما اهل وفای به عهد و امانت‌داری هستند.", "source": "الكافي، جلد ۲، صفحه ۸۵"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): إِذَا أَحَبَّ اللَّهُ عَبْداً حَبَّبَ إِلَيْهِ الْأَمَانَةَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هرگاه خداوند بنده‌ای را دوست بدارد، امانت‌داری را محبوب قلب او می‌سازد.", "source": "میزان الحکمة، جلد ۲، صفحه ۴۳۸"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): لَا إِيمَانَ لِمَنْ لَا أَمَانَةَ لَهُ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: کسی که امانت‌دار نیست، ایمانی ندارد.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۱۹۸"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): رَأْسُ الْإِسْلَامِ الْأَمَانَةُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: سرآمد و اساس اسلام، امانت‌داری است.", "source": "غرر الحكم، صفحه ۴۷"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): أَدِّ الْأَمَانَةَ إِلَى مَنِ ائْتَمَنَكَ وَ لَا تَخُنْ مَنْ خَانَكَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: امانت را به کسی که به تو اعتماد کرده است بازگردان و به کسی که خیانت کرده، خیانت مکن.", "source": "من لا يحضره الفقيه، جلد ۴، صفحه ۱۵"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): أَفْضَلُ الْإِيمَانِ الْأَمَانَةُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: برترین درجه ایمان، امانت‌داری است.", "source": "غرر الحكم، صفحه ۴۷"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): آيَةُ الْمُنَافِقِ ثَلَاثٌ: إِذَا حَدَّثَ كَذَبَ، وَ إِذَا وَعَدَ أَخْلَفَ، وَ إِذَا اؤْتُمِنَ خَانَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: نشانه منافق سه چیز است: چون سخن گوید دروغ گوید، چون وعده دهد تخلف کند، و چون امین شمرده شود خیانت نماید.", "source": "الكافي، جلد ۲، صفحه ۲۹۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنْ خَانَ أَمَانَةً فِي الدُّنْيَا فَقَدْ بَرِئَ مِنْ وِلَايَتِنَا.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس در دنیا به امانتی خیانت کند، قطعاً از ولایت ما خارج شده است.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۱۷۱"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنِ ائْتَمَنَ خَائِناً نَدِمَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس فرد خائنی را امین بشمرد، پشیمان می‌گردد.", "source": "غرر الحكم، صفحه ۳۷۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): صَاحِبُ الْأَمَانَةِ فِي كَنَفِ اللَّهِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: صاحب امانت (فرد امین) در پناه پروردگار است.", "source": "مستدرك الوسائل، جلد ۱۴، صفحه ۱۳"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّ عَلِيّاً (علیه‌السلام) بَلَغَ مَا بَلَغَ بِهِ عِنْدَ رَسُولِ اللَّهِ (صلی‌الله‌علیه‌وآله) بِصِدْقِ الْحَدِيثِ وَ أَدَاءِ الْأَمَانَةِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: همانا علی (علیه‌السلام) نزد پیامبر خدا به آن مقامات عالی نرسید مگر با راست‌گویی و ادای امانت.", "source": "الكافي، جلد ۲، صفحه ۱۰۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الْأَمَانَةُ طُمَأْنِينَةٌ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: امانت‌داری مایه آرامش و طمأنینه است.", "source": "غرر الحكم، صفحه ۴۷"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): إِيَّاكُمْ وَ الْخِيَانَةَ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ.", "translation": "امام باقر (علیه‌السلام) فرمودند: از خیانت بپرهیزید که آن بدترین خصلت باطنی است.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۱۷۱"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): الْأَمِينُ مُخْتَارُ اللَّهِ فِي الْأَرْضِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: فرد امین، برگزیده خداوند در روی زمین است.", "source": "مستدرك الوسائل، جلد ۱۴، صفحه ۱۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنْ رَعَى الْأَمَانَةَ وَقَاهُ اللَّهُ خِيَانَةَ الزَّمَانِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس امانت را پاس بدارد، خداوند او را از خیانت روزگار حفظ می‌کند.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۱۷۱"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): ضَيَاعُ الْأَمَانَةِ شَقَاوَةٌ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: تباه کردن امانت، نشانه بدبختی است.", "source": "غرر الحكم، صفحه ۲۱۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ ائْتُمِنَ عَلَى أَمَانَةٍ فَأَدَّاهَا كَتَبَ اللَّهُ لَهُ ثَوَابَ أَلْفِ شَهِيدٍ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر کس امانتی به او سپرده شود و آن را ادا کند، خداوند ثواب هزار شهید را برایش می‌نویسد.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۱۷۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): ثَلَاثَةٌ هُنَّ مِنْ مَكَارِمِ الْأَخْلَاقِ: إِعْطَاءُ السَّائِلِ، وَ الْعَفْوُ عَنِ الْمُسِيءِ، وَ أَدَاءُ الْأَمَانَةِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: سه چیز از مکارم اخلاق است: بخشش به نیازمند، گذشت از خطاکار و ادای امانت.", "source": "وسائل الشيعة، جلد ۱۹، صفحه ۷۵"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): غَايَةُ الدِّينِ الْأَمَانَةُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: نهایت و کمال دین، امانت‌داری است.", "source": "غرر الحكم، صفحه ۴۷"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): لَا تَخُنْ مَنْ خَانَكَ فَتَكُونَ مِثْلَهُ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: به کسی که به تو خیانت کرده خیانت مکن، که در آن صورت همانند او خواهی بود.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۱۷۱"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): الْأَمَانَةُ نُورٌ فِي الْقَلْبِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: امانت‌داری، نوری در قلب است.", "source": "بحار الأنوار، جلد ۷۵، صفحه ۱۱۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): إِيَّاكَ وَ الْخِيَانَةَ فَإِنَّهَا شَرُّ مَعْصِيَةٍ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: از خیانت بپرهیز که مسلماً بدترین گناه است.", "source": "غرر الحكم، صفحه ۱۵۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): رَدُّ الْأَمَانَةِ مِنْ كَمَالِ الْإِيمَانِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: بازگرداندن امانت از نشانه‌های کمال ایمان است.", "source": "مستدرك الوسائل، جلد ۱۴، صفحه ۱۲"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَقْرَبُكُمْ مِنِّي غَداً فِي الْمَوْقِفِ أَصْدَقُكُمْ لِلْحَدِيثِ وَ آدَاكُمْ لِلْأَمَانَةِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: نزدیک‌ترین شما به من در روز قیامت، راست‌گوترین شما و امانت‌دارترین شماست.", "source": "بحار الأنوار، جلد ۷۲، صفحه ۹۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الْأَمَانَةُ سَجِيَّةُ الْأَخْيَارِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: امانت‌داری سرشت نیکوکاران است.", "source": "غرر الحكم، صفحه ۴۷"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِذَا أُعْطِيَ الشَّكُورُ أُعْطِيَ الزِّيَادَةَ لِقَوْلِ اللَّهِ لَئِنْ شَكَرْتُمْ لَأَزِيدَنَّكُمْ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هنگامی که به فرد شکرگزار نعمتی عطا شود، فزونی نیز به او داده می‌شود؛ به دلیل قول خداوند: اگر شکر کنید بر شما می‌افزایم.", "source": "الكافي، جلد ۲، صفحه ۹۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): شُكْرُ النِّعْمَةِ أَمَانٌ مِنَ الْغِيَرِ وَ يَسْتَوْجِبُ الزِّيَادَةَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: شکر نعمت، امانی در برابر دگرگونی‌هاست و فزونی را واجب می‌گرداند.", "source": "بحار الأنوار، جلد ۷۵، صفحه ۳۷۰"},
        {"text": "قَالَ الرِّضَا (علیه‌السلام): مَنْ لَمْ يَشْكُرِ الْمُنْعِمَ مِنَ الْمَخْلُوقِينَ لَمْ يَشْكُرِ اللَّهَ عَزَّ وَ جَلَّ.", "translation": "امام رضا (علیه‌السلام) فرمودند: هر کس از انسان‌های نعمت‌دهنده شکرگزاری نکند، خداوند عزوجل را شکر نکرده است.", "source": "وسائل الشيعة، جلد ۱۶، صفحه ۳۱۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَشْكَرُكُمْ لِلَّهِ أَشْكَرُكُمْ لِلنَّاسِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: سپاسگزارترین شما برای خدا، سپاسگزارترین شما از مردم است.", "source": "الكافي، جلد ۲، صفحه ۹۹"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): لَا تَنْقَطِعُ الزِّيَادَةُ مِنَ اللَّهِ حَتَّى يَنْقَطِعَ الشُّكْرُ مِنَ الْعِبَادِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: فزونی نعمت از جانب خدا قطع نمی‌شود تا زمانی که شکرگزاری بندگان قطع گردد.", "source": "تحف العقول، صفحه ۲۳۰"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): الْبَرَكَةُ فِي ثَلَاثٍ: الصَّدَقَةِ وَ الْمُبَاكَرَةِ وَ الْأَمَانَةِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: برکت در سه چیز است: صدقه دادن، سحرخیزی در کار و امانت‌داری.", "source": "بحار الأنوار، جلد ۷۳، صفحه ۱۷۷"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): شُكْرُ كُلِّ نِعْمَةٍ الْوَرَعُ عَمَّا حَرَّمَ اللَّهُ.", "translation": "امام صادق (علیه‌السلام) فرمودند: شکر واقعی هر نعمتی، پرهیز از محرمات الهی است.", "source": "الكافي، جلد ۲، صفحه ۹۵"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الْحَمْدُ لِلَّهِ عَلَى كُلِّ نِعْمَةٍ كَانَتْ أَوْ هِيَ كَائِنَةٌ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: ستایش مخصوص خداوند است بر هر نعمتی که بوده و یا به وجود خواهد آمد.", "source": "بحار الأنوار، جلد ۹۱، صفحه ۲۰۴"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ اللَّهَ لَيُرْضِى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الْأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: همانا خداوند راضی می‌شود از بنده‌ای که غذایی بخورد و بابت آن خدا را شکر گوید.", "source": "مستدرك الوسائل، جلد ۱۶، صفحه ۲۴۰"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): شُكْرُ النِّعَمِ يُضاعِفُ النِّعَمَ وَ يُوجِبُ الْمَزِيدَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: شکر نعمت‌ها، آنها را دوچندان کرده و فزونی را واجب می‌سازد.", "source": "غرر الحكم، صفحه ۱۸۰"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): تَمَامُ النِّعْمَةِ الشُّكْرُ عَلَيْهَا.", "translation": "امام باقر (علیه‌السلام) فرمودند: کمال نعمت در آن است که شکر آن به جای آورده شود.", "source": "بحار الأنوار، جلد ۶۸، صفحه ۵۳"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَنْ رُزِقَ الشُّكْرَ لَمْ يُحْرَمِ الزِّيَادَةَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هر کس روزی‌اش شکرگزاری شود، هرگز از فزونی نعمت محروم نمی‌گردد.", "source": "الكافي، جلد ۲، صفحه ۹۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): لَوْ كَانَ عِنْدَ اللَّهِ عِبَادَةٌ أَفْضَلَ مِنَ الشُّكْرِ لَافْتَرَضَهَا عَلَى عِبَادِهِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: اگر نزد خداوند عبادتی برتر از شکرگزاری بود، همان را بر بندگانش واجب می‌ساخت.", "source": "مستدرك الوسائل، جلد ۱۱، صفحه ۳۵۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): فِي الشُّكْرِ تَكُونُ النِّعْمَةُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: نعمت تنها با شکرگزاری پایدار می‌ماند.", "source": "غرر الحكم، صفحه ۱۸۰"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَوَّلُ مَنْ يُدْعَى إِلَى الْجَنَّةِ يَوْمَ الْقِيَامَةِ الْحَمَّادُونَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: نخستین کسانی که در روز قیامت به بهشت فراخوانده می‌شوند، بسیار ستایش‌کنندگان خداوند هستند.", "source": "بحار الأنوار، جلد ۶۸، صفحه ۳۳"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): النِّعْمَةُ مُوَصَّلَةٌ بِالشُّكْرِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: نعمت‌ها به واسطه شکرگزاری به یکدیگر متصل می‌شوند.", "source": "الكافي، جلد ۲، صفحه ۹۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): بِالشُّكْرِ تُسْتَجْلَبُ النِّعَمُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: با شکرگزاری است که نعمت‌ها جلب می‌شوند.", "source": "غرر الحكم، صفحه ۱۸۰"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): مَنْ شَكَرَ اللَّهَ زَادَهُ مِنْ فَضْلِهِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: هر کس خدا را شکر گوید، خداوند از فضل خویش بر او می‌افزاید.", "source": "بحار الأنوار، جلد ۶۸، صفحه ۵۴"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): التَّحَدُّثُ بِنِعْمَةِ اللَّهِ شُكْرٌ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: بازگو کردن نعمت‌های خداوند، خود نوعی شکرگزاری است.", "source": "وسائل الشيعة، جلد ۱۶، صفحه ۳۱۲"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ لَمْ يَشْكُرِ النِّعْمَةَ عُوقِبَ بِزَوَالِهَا.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس شکر نعمت را به جای نیاورد، با زوال آن نعمت مجازات می‌شود.", "source": "غرر الحكم، صفحه ۱۸۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِذَا ذَكَرْتَ نِعْمَةَ اللَّهِ فَضَعْ خَدَّكَ عَلَى التُّرَابِ شُكْراً.", "translation": "امام صادق (علیه‌السلام) فرمودند: هرگاه نعمتی از خدا را به یاد آوردی، به نشانه شکرگونه چهره بر خاک بنه.", "source": "الكافي، جلد ۲، صفحه ۹۸"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): الدُّعَاءُ مِفْتَاحُ الرَّحْمَةِ وَ الشُّكْرُ مِفْتَاحُ الزِّيَادَةِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: دعا کلید رحمت است و شکرگزاری کلید فزونی.", "source": "بحار الأنوار، جلد ۹۰، صفحه ۳۰۰"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): شُكْرُ الْمُؤْمِنِ يَظْهَرُ فِي عَمَلِهِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: شکر مؤمن در عمل و کردار او آشکار می‌شود.", "source": "غرر الحكم، صفحه ۱۸۱"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): لَا تَنْسَ شُكْرَ مَنْ أَنْعَمَ عَلَيْكَ.", "translation": "امام باقر (علیه‌السلام) فرمودند: شکرگزاری از کسی را که به تو نعمتی داده فراموش مکن.", "source": "بحار الأنوار، جلد ۷۱، صفحه ۳۰"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَحْسَنُ النَّاسِ إِيمَاناً أَشْكَرُهُمْ لِلنِّعَمِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: نیکوترین مردم در ایمان، شکرگزارترین آن‌ها در برابر نعمت‌هاست.", "source": "مستدرك الوسائل، جلد ۱۱، صفحه ۳۵۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): كُفْرَانُ النِّعَمِ مُزِيلُهَا.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: کفران نعمت‌ها، زایل‌کننده و از بین برنده آن‌هاست.", "source": "غرر الحكم، صفحه ۳۷۶"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الْمَالُ مَالُ اللَّهِ وَ جَعَلَهُ وَدَائِعَ عِنْدَ خَلْقِهِ لِيَشْكُرُوهُ.", "translation": "امام صادق (علیه‌السلام) فرمودند: دارایی از آنِ خداست و آن را به عنوان امانت نزد خلقش قرار داده تا او را شکر گویند.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۲۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): الصِّحَّةُ وَ الْفَرَاغُ نِعْمَتَانِ مَكْفُورَتَانِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: سلامتی و فراغت دو نعمتی هستند که اغلب ناسپاسی می‌شوند.", "source": "بحار الأنوار، جلد ۷۴، صفحه ۱۵۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ أُلْهِمَ الشُّكْرَ لَمْ يُحْرَمِ الزِّيَادَةَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس شکرگزاری به او الهام شود، از فزونی نعمت محروم نگردد.", "source": "نهج البلاغة، حکمت ۱۳۵"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): الزِّيَادَةُ مِنَ اللَّهِ مَقْرُونَةٌ بِالشُّكْرِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: فزونی از جانب خدا با شکرگزاری پیوند خورده است.", "source": "بحار الأنوار، جلد ۶۸، صفحه ۵۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الْكَادُّ عَلَى عِيَالِهِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: کسی که برای تأمین خانواده‌اش زحمت می‌کشد، مانند جهادگر در راه خداست.", "source": "الكافي، جلد ۵، صفحه ۸۸"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): مَنْ طَلَبَ الدُّنْيَا اسْتِعْفَافاً عَنِ النَّاسِ لَقِيَ اللَّهَ وَ وَجْهُهُ كَالْقَمَرِ فِي لَيْلَةِ الْبَدْرِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: هر کس دنیا را برای بی‌نیازی از مردم طلب کند، خدا را در حالی ملاقات کند که چهره‌اش چون ماه شب چهارده می‌درخشد.", "source": "الكافي، جلد ۵، صفحه ۷۸"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ اللَّهَ عَزَّ وَ جَلَّ يُبْغِضُ الْعَبْدَ النَّوَّامَ الْفَارِغَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: همانا خداوند عز و جل بنده بسیار خواب‌آلوده و بی‌کار را دشمن می‌دارد.", "source": "الكافي، جلد ۵، صفحه ۸۴"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): يَا هِشَامُ إِنْ رَأَيْتَ الصَّفَّيْنِ قَدِ الْتَقَيَا فَلَا تَدَعْ طَلَبَ الرِّزْقِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: ای هشام! حتی اگر دیدی دو لشکر برای جنگ صف کشیده‌اند، تلاش برای کسب روزی را رها مکن.", "source": "الكافي، جلد ۵، صفحه ۷۸"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ مِنَ الذُّنُوبِ ذُنُوباً لَا يُكَفِّرُهَا صَلَاةٌ وَ لَا صَدَقَةٌ، قِيلَ فَمَا يُكَفِّرُهَا؟ قَالَ الْهُمُومُ فِي طَلَبِ الْمَعِيشَةِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: برخی از گناهان است که هیچ نماز و صدقه‌ای آن‌ها را پاک نمی‌سازد؛ پرسیدند: پس چه چیز آن‌ها را پاک می‌کند؟ فرمود: رنج و تلاش در طلب معیشت.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۱۳"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): مَا أَكَلَ أَحَدٌ طَعَاماً قَطُّ خَيْراً مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: هیچ کس هرگز غذایی بهتر از دسترنج خویش نخورده است.", "source": "بحار الأنوار، جلد ۶۶، صفحه ۳۱۴"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): الْمُؤْمِنُ حَرِيصٌ عَلَى الْجِدِّ وَ الِاجْتِهَادِ فِي الْعَمَلِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: مؤمن تشنه و حریص بر تلاش و کوشایی فراوان در کار خویش است.", "source": "غرر الحكم، صفحه ۸۹"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): بَاكِرُوا فِي طَلَبِ الرِّزْقِ فَإِنَّ الْبَرَكَةَ فِي الْمُبَاكَرَةِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: صبح زود در پی روزی بروید؛ زیرا که برکت در سحرخیزی است.", "source": "الأمالي للصدوق، صفحه ۲۸۹"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): عَلَيْكُمْ بِالْجِدِّ وَ الِاجْتِهَادِ وَ التَّأَهُّبِ وَ الِاسْتِعْدَادِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: بر شما باد به تلاش و کوشش پیگیر و آماده‌باش و مجهز شدن در کارها.", "source": "نهج البلاغة، خطبه ۲۳۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): لَا تَكْسَلْ عَنْ مَعِيشَتِكَ فَتَكُونَ كَلًّا عَلَى غَيْرِكَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: در کار معیشت خود سستی مکن که سربار دیگران خواهی شد.", "source": "وسائل الشيعة، جلد ۱۲، صفحه ۳۷"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ اللَّهَ يُحِبُّ الْمُؤْمِنَ الْمُحْتَرِفَ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: همانا خداوند مؤمن صاحب حرفه و تلاشگر را دوست دارد.", "source": "الكافي، جلد ۵، صفحه ۱۱۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ يَعْمَلْ يَزْدَدْ قُوَّةً.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس کار و تلاش کند، بر نیروی او افزوده می‌شود.", "source": "غرر الحكم، صفحه ۳۱۵"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): إِنِّي لَأُبْغِضُ الرَّجُلَ أَنْ يَكُونَ كَسْلَاناً عَنْ أَمْرِ دُنْيَاهُ.", "translation": "امام باقر (علیه‌السلام) فرمودند: من دشمن می‌دارم مردی را که در کار دنیای خود تنبل باشد.", "source": "الكافي، جلد ۵، صفحه ۸۵"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): اقْعُدْ فِي دُكَّانِكَ وَ ابْسُطْ بِسَاطَكَ.", "translation": "امام صادق (علیه‌السلام) فرمودند: در دکان خویش بنشین و بساط کسبت را پهن کن (کنایه از لزوم حضور در میدان کار).", "source": "الكافي، جلد ۵، صفحه ۱۴۹"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): الشَّاخِصُ فِي طَلَبِ الرِّزْقِ الْحَلَالِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: کسی که در پی روزی حلال در حرکت و تکاپو است، مانند مجاهد در راه خداست.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۱۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): بِالْعَمَلِ يَحْصُلُ الثَّوَابُ لَا بِالْكَسَلِ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: پاداش با کار و تلاش به دست می‌آید، نه با تنبلی.", "source": "غرر الحكم، صفحه ۱۳۰"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): إِنَّ اللَّهَ لَيُحِبُّ الِاغْتِرَابَ فِي طَلَبِ الرِّزْقِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: خداوند مسافرت و غربت را برای طلب روزی دوست دارد.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۲۶"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): أَيُّمَا رَجُلٍ سَعَى عَلَى عِيَالِهِ كَانَ فِي وِلَايَةِ اللَّهِ.", "translation": "امام باقر (علیه‌السلام) فرمودند: هر مردی که برای تأمین خانواده‌اش تلاش کند، در سرپرستی و پناه خداوند است.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۱۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ قَصَّرَ فِي الْعَمَلِ ابْتُلِيَ بِالْهَمِّ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس در کار و تلاش کوتاهی کند، به اندوه مبتلا می‌شود.", "source": "نهج البلاغة، حکمت ۱۲۷"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): إِنَّ النَّفْسَ إِذَا أَحْرَزَتْ قُوتَهَا اسْتَقَرَّتْ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: همانا جان آدمی هرگاه با تلاش آذوقه‌اش را تأمین کند، آرامش می‌یابد.", "source": "الكافي، جلد ۵، صفحه ۸۹"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الْجَالِسُ عَنِ الطَّلَبِ كَالْمُنْتَظِرِ لِلْغَارَةِ.", "translation": "امام صادق (علیه‌السلام) فرمودند: کسی که از تلاش دست می‌کشد، مانند کسی است که منتظر غارت شدن اموالش است.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۳۰"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): طَلَبُ الْمَعَايِشِ يُنَمِّي الْعُقُولَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: تلاش برای معیشت، عقل‌ها را رشد داده و بارور می‌کند.", "source": "غرر الحكم، صفحه ۲۳۸"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): مَنْ طَلَبَ الرِّزْقَ فَهُوَ فِي عِبَادَةٍ.", "translation": "امام باقر (علیه‌السلام) فرمودند: هر کس در پی روزی رود، در حال عبادت است.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۵"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): أَفْضَلُ الْأَعْمَالِ الْكَسْبُ مِنَ الْحَلَالِ.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: برترین کارها، کسب درآمد از راه حلال با تلاش است.", "source": "مستدرك الوسائل، جلد ۱۳، صفحه ۱۲"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): اعْمَلْ لِدُنْيَاكَ كَأَنَّكَ تَعِيشُ أَبَداً.", "translation": "امام صادق (علیه‌السلام) فرمودند: برای دنیای خود با تلاش چنان کار کن که گویی همیشه زنده‌ای.", "source": "وسائل الشيعة، جلد ۱۷، صفحه ۷۶"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): مَنْ عَمِلَ أُجِرَ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: هر کس کار و تلاش کند، پاداش می‌یابد.", "source": "غرر الحكم، صفحه ۳۱۵"},
        {"text": "قَالَ أَبُو جَعْفَرٍ (علیه‌السلام): إِنَّ الطَّلَبَ لِلرِّزْقِ مَحْمُودٌ.", "translation": "امام باقر (علیه‌السلام) فرمودند: همانا تلاش برای روزی، کاری پسندیده و ستایش شده است.", "source": "بحار الأنوار، جلد ۱۰۳، صفحه ۴"},
        {"text": "قَالَ رَسُولُ اللَّهِ (صلی‌الله‌علیه‌وآله): بَارَكَ اللَّهُ لِأُمَّتِي فِي بُكُورِهَا.", "translation": "پیامبر اکرم (صلی‌الله‌علیه‌وآله) فرمودند: خداوند برای امت من در صبحگاهان (و آغاز زودهنگام تلاش) برکت قرار داده است.", "source": "من لا يحضره الفقيه، جلد ۳، صفحه ۱۵۷"},
        {"text": "قَالَ أَبُو عَبْدِ اللَّهِ (علیه‌السلام): الْعَمَلُ دِينٌ.", "translation": "امام صادق (علیه‌السلام) فرمودند: کار و تلاش کردن، عین دین‌داری است.", "source": "الكافي، جلد ۵، صفحه ۷۳"},
        {"text": "قَالَ أَمِيرُ الْمُؤْمِنِينَ (علیه‌السلام): لَا شَرَفَ مَعَ سُوءِ الْأَدَبِ وَ لَا رَاحَةَ لِمَنْ لَا يَعْمَلُ.", "translation": "امیرالمؤمنین (علیه‌السلام) فرمودند: با بی‌ادبی شرافتی نیست و برای کسی که کار نمی‌کند راحتی نیست.", "source": "غرر الحكم، صفحه ۳۸۴"},
        {"text": "وَهُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِ نَبَاتَ كُلِّ شَيْءٍ.", "translation": "و اوست كسی كه از آسمان آبی فرستاد، پس به وسیله آن گیاه هر چیزی را [از زمین] بیرون آوردیم.", "source": "سوره انعام، آیه ۹۹"},
        {"text": "وَآيَةٌ لَهُمُ الْأَرْضُ الْمَيْتَةُ أَحْيَيْنَاهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ.", "translation": "و نشانه‌ای برای آن‌ها زمین مرده است که آن را زنده کردیم و از آن دانه خارج ساختیم، پس از آن می‌خورند.", "source": "سوره یس، آیه ۳۳"},
        {"text": "وَجَعَلْنَا فِيهَا جَنَّاتٍ مِنْ نَخِيلٍ وَأَعْنَابٍ وَفَجَّرْنَا فِيهَا مِنَ الْعُيُونِ.", "translation": "و در آن باغ‌هایی از درختان خرما و انگور قرار دادیم و چشمه‌هایی در آن جاری ساختیم.", "source": "سوره یس، آیه ۳۴"},
        {"text": "لِيَأْكُلُوا مِنْ ثَمَرِهِ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ.", "translation": "تا از میوه آن و دسترنج خود بخورند؛ آیا سپاسگزاری نمی‌کنند؟", "source": "سوره یس، آیه ۳۵"},
        {"text": "أَفَرَأَيْتُمْ مَا تَحْرُثُونَ * أَأَنْتُمْ تَزْرَعُونَهُ أَمْ نَحْنُ الزَّارِعُونَ.", "translation": "آیا درباره آنچه کشت می‌کنید اندیشیده‌اید؟ آیا شما آن را می‌رویانید یا ما می‌رویانیم؟", "source": "سوره واقعه، آیات ۶۳-۶۴"},
        {"text": "وَهُوَ الَّذِي أَنْشَأَ جَنَّاتٍ مَعْرُوشَاتٍ وَغَيْرَ مَعْرُوشَاتٍ وَالنَّخْلَ وَالزَّرْعَ مُخْتَلِفًا أُكُلُهُ.", "translation": "و اوست که باغ‌هایی داربست‌دار و بدون داربست، و درختان خرما و زراعت با طعم‌های گوناگون پدید آورد.", "source": "سوره انعام، آیه ۱۴۱"},
        {"text": "يُنْبِتُ لَكُمْ بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخِيلَ وَالْأَعْنَابَ وَمِنْ كُلِّ الثَّمَرَاتِ.", "translation": "به وسیله آن برای شما زراعت و زیتون و خرما و انگور و از همه میوه‌ها می‌رویند.", "source": "سوره نحل، آیه ۱۱"},
        {"text": "وَفِي الْأَرْضِ قِطَعٌ مُتَجَاوِرَاتٌ وَجَنَّاتٌ مِنْ أَعْنَابٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ.", "translation": "و در زمین قطعاتی همجوار و باغ‌هایی از انگور و کشتزارها و درختان خرما است که هم ریشه‌اند و هم غیر هم‌ریشه.", "source": "سوره رعد، آیه ۴"},
        {"text": "وَأَنْزَلْنَا مِنَ السَّمَاءِ مَاءً مُبَارَكًا فَأَنْبَتْنَا بِهِ جَنَّاتٍ وَحَبَّ الْحَصِيدِ.", "translation": "و از آسمان آبی پر برکت فرستادیم و بدان باغ‌ها و دانه‌های دروشدنی رویاندیم.", "source": "سوره ق، آیه ۹"},
        {"text": "ثُمَّ شَقَقْنَا الْأَرْضَ شَقًّا * فَأَنْبَتْنَا فِيهَا حَبًّا * وَعِنَبًا وَقَضْبًا.", "translation": "سپس زمین را به خوبی شکافتیم، و در آن دانه‌ها رویاندیم، و انگور و سبزی‌های خوردنی.", "source": "سوره عبس، آیات ۲۶-۲۸"},
        {"text": "وَزَيْتُونَاً وَنَخْلَاً * وَحَدَائِقَ غُلْبَاً * وَفَاكِهَةً وَأَبَّاً.", "translation": "و زیتون و نخل، و باغ‌های انبوه، و میوه‌ها و چراگاه‌ها.", "source": "سوره عبس، آیات ۲۹-۳۱"},
        {"text": "مَتَاعًا لَكُمْ وَلِأَنْعَامِكُمْ.", "translation": "تا مایه بهره‌مندی شما و چهارپایانتان باشد.", "source": "سوره عبس، آیه ۳۲"},
        {"text": "أَوَلَمْ يَرَوْا أَنَّا نَسُوقُ الْمَاءَ إِلَى الْأَرْضِ الْجُرُزِ فَنُخْرِجُ بِهِ زَرْعًا.", "translation": "آیا ندیدند که ما آب را به سوی زمین خشک و بی‌گیاه می‌رانیم، پس به وسیله آن زراعتی بیرون می‌آوریم؟", "source": "سوره سجده، آیه ۲۷"},
        {"text": "يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا.", "translation": "ای مردم! از آنچه در زمین حلال و پاکیزه است بخورید.", "source": "سوره بقره، آیه ۱۶۸"},
        {"text": "يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلَّهِ.", "translation": "ای کسانی که ایمان آورده‌اید! از نعمت‌های پاکیزه‌ای که به شما روزی داده‌ایم بخورید و شکر خدا را به جای آورید.", "source": "سوره بقره، آیه ۱۷۲"},
        {"text": "فَكُلُوا مِمَّا غَنِمْتُمْ حَلَالًا طَيِّبًا وَاتَّقُوا اللَّهَ.", "translation": "پس از آنچه به غنیمت برده‌اید، حلال و پاکیزه بخورید و از خدا پروا کنید.", "source": "سوره انفال، آیه ۶۹"},
        {"text": "فَكُلُوا مِمَّا رَزَقَكُمُ اللَّهُ حَلَالًا طَيِّبًا وَاشْكُرُوا نِعْمَتَ اللَّهِ.", "translation": "پس از آنچه خدا روزی شما کرده است، حلال و پاکیزه بخورید و نعمت خدا را سپاس گویید.", "source": "سوره نحل، آیه ۱۱۴"},
        {"text": "يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا.", "translation": "ای پیامبران! از غذاهای پاکیزه [و حلال] بخورید و کار شایسته انجام دهید.", "source": "سوره مؤمنون، آیه ۵۱"},
        {"text": "فَكُلُوا مِمَّا رَزَقَكُمُ اللَّهُ حَلَالًا طَيِّبًا وَاتَّقُوا اللَّهَ الَّذِي أَنْتُمْ بِهِ مُؤْمِنُونَ.", "translation": "و از آنچه خداوند روزی شما گردانیده، حلال و پاکیزه بخورید و از خدایی که به او ایمان دارید پروا کنید.", "source": "سوره مائده، آیه ۸۸"},
        {"text": "يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ.", "translation": "از تو می‌پرسند چه چیزی برای آنان حلال شده است؟ بگو: چیزهای پاکیزه [و حلال] برای شما حلال شده است.", "source": "سوره مائده، آیه ۴"},
        {"text": "كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَلَا تَطْغَوْا فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي.", "translation": "از نعمت‌های پاکیزه‌ای که روزی شما کردیم بخورید و در آن طغیان نکنید که خشم من بر شما فرود می‌آید.", "source": "سوره طه، آیه ۸۱"},
        {"text": "هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِنْ رِزْقِهِ.", "translation": "اوست کسی که زمین را برای شما رام گردانید، پس در گوشه و کنار آن راه بروید و از روزی او بخورید.", "source": "سوره ملک، آیه ۱۵"},
        {"text": "وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا.", "translation": "و هیچ جنبنده‌ای در زمین نیست مگر اینکه روزی او بر عهده خداست.", "source": "سوره هود، آیه ۶"},
        {"text": "وَلَقَدْ مَكَّنَّاكُمْ فِي الْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَايِشَ قَلِيلًا مَا تَشْكُرُونَ.", "translation": "و همانا ما شما را در زمین تمکن بخشیدیم و برای شما در آن وسایل زندگی قرار دادیم، اما اندکی سپاسگزاری می‌کنید.", "source": "سوره اعراف، آیه ۱۰"},
        {"text": "وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ * مَا أُرِيدُ مِنْهُمْ مِنْ رِزْقٍ وَمَا أُرِيدُ أَنْ يُطْعِمُونِ.", "translation": "و جن و انس را نیافریدم جز برای آنکه مرا بپرستند. از آنان هیچ روزی‌ای نمی‌خواهم و نمی‌خواهم که به من غذا دهند.", "source": "سوره ذاریات، آیات ۵۶-۵۷"},
        {"text": "يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ.", "translation": "ای کسانی که ایمان آورده‌اید! اموال یکدیگر را در میان خود به باطل [و ناحق] نخورید.", "source": "سوره نساء، آیه ۲۹"},
        {"text": "وَلَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ لِتَأْكُلُوا فَرِيقًا مِنْ أَمْوَالِ النَّاسِ بِالْإِثْمِ.", "translation": "و اموالتان را میان خود به باطل نخورید و آن را [به عنوان رشوه] به سوی حاکمان سرازیر نکنید تا بخشی از اموال مردم را به گناه بخورید.", "source": "سوره بقره، آیه ۱۸۸"},
        {"text": "إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا إِنَّمَا يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا.", "translation": "همانا کسانی که اموال یتیمان را به ستم می‌خورند، جز این نیست که در شکم‌های خود آتش می‌خورند.", "source": "سوره نساء، آیه ۱۰"},
        {"text": "وَيْلٌ لِلْمُطَفِّفِينَ * الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ.", "translation": "وای بر کم‌فروشان! آنان که چون از مردم پیمانه می‌ستانند، کامل می‌گیرند.", "source": "سوره مطففین، آیات ۱-۲"},
        {"text": "وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ.", "translation": "و چون برای آنان پیمانه یا وزن می‌کنند، کم می‌گذارند.", "source": "سوره مطففین، آیه ۳"},
        {"text": "وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا.", "translation": "و پیمانه و ترازو را به عدالت تمام و کمال بدهید؛ ما هیچ کس را جز به اندازه توانش مکلف نمی‌کنیم.", "source": "سوره انعام، آیه ۱۵۲"},
        {"text": "أَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ.", "translation": "پیمانه را تمام و کمال بدهید و از خسارت‌کاران مباشید.", "source": "سوره شعراء، آیه ۱۸۱"},
        {"text": "وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ.", "translation": "و با ترازوی درست و مستقیم وزن کنید.", "source": "سوره شعراء، آیه ۱۸۲"},
        {"text": "وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ.", "translation": "و از حقوق مردم و چیزهای آنان کم نگذارید و در زمین به فساد و تبهکاری نکوشید.", "source": "سوره شعراء، آیه ۱۸۳"},
        {"text": "فَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا.", "translation": "پس پیمانه و ترازو را تمام دهید و از چیزهای مردم کم نگذارید و در زمین پس از اصلاح آن فساد نکنید.", "source": "سوره اعراف، آیه ۸۵"},
        {"text": "وَيَا قَوْمِ أَوْفُوا الْمِكْيَالَ وَالْمِيزَانَ بِالْقِسْطِ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ.", "translation": "و ای قوم من! پیمانه و ترازو را به عدالت تمام دهید و به مردم و کالاهایشان کم‌فروشی نکنید.", "source": "سوره هود، آیه ۸۵"},
        {"text": "وَأَقِيمُوا الْوَزْنَ بِالْقِسْطِ وَلَا تُخْسِرُوا الْمِيزَانَ.", "translation": "و وزن را به عدالت برپا دارید و در سنجش و ترازو کم نگذارید.", "source": "سوره الرحمن، آیه ۹"},
        {"text": "وَأَوْفُوا الْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا.", "translation": "و چون پیمانه می‌کنید، آن را تمام دهید و با ترازوی درست وزن کنید که این کار بهتر و خوش‌سرانجام‌تر است.", "source": "سوره اسراء، آیه ۳۵"},
        {"text": "إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا.", "translation": "همانا خداوند به شما فرمان می‌دهد که امانت‌ها را به صاحبانشان بازگردانید.", "source": "سوره نساء، آیه ۵۸"},
        {"text": "وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ.", "translation": "و کسانی که امانت‌ها و پیمان خود را رعایت می‌کنند.", "source": "سوره مؤمنون، آیه ۸"},
        {"text": "يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ.", "translation": "ای کسانی که ایمان آورده‌اید! به خدا و پیامبر خیانت نکنید و در امانت‌های خود نیز آگاهانه خیانت نورزید.", "source": "سوره انفال، آیه ۲۷"},
        {"text": "فَإِنْ أَمِنَ بَعْضُكُمْ بَعْضًا فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ أَمَانَتَهُ وَلْيَتَّقِ اللَّهَ رَبَّهُ.", "translation": "پس اگر یکی از شما دیگری را امین دانست، آن کس که امین شمرده شده باید امانتش را بازپس دهد و از پروردگارش پروا کند.", "source": "سوره بقره، آیه ۲۸۳"},
        {"text": "وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ.", "translation": "و کسانی که امانت‌ها و پیمان‌های خود را مراقبت و رعایت می‌کنند.", "source": "سوره معارج، آیه ۳۲"},
        {"text": "وَمِنْ أَهْلِ الْكِتَابِ مَنْ إِنْ تَأْمَنْهُ بِقِنْطَارٍ يُؤَدِّهِ إِلَيْكَ.", "translation": "و از اهل کتاب کسی است که اگر او را بر مال فراوانی امین شمری، آن را به تو باز می‌گرداند.", "source": "سوره آل عمران، آیه ۷۵"},
        {"text": "قَالَتْ إِحْدَاهُمَا يَا أَبَتِ اسْتَأْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ.", "translation": "یکی از آن دو دختر گفت: ای پدر! او را استخدام کن، چرا که بهترین کسی که می‌توانی استخدام کنی آن کسی است که نیرومند و امین باشد.", "source": "سوره قصص، آیه ۲۶"},
        {"text": "إِنِّي لَكُمْ رَسُولٌ أَمِينٌ.", "translation": "همانا من برای شما فرستاده‌ای امین و درستکار هستم.", "source": "سوره شعراء، آیه ۱۰۶"},
        {"text": "إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَاوَاتِ وَالْأَرْضِ وَالْجِبَالِ فَأَبَيْنَ أَنْ يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا.", "translation": "همانا ما امانت را بر آسمان‌ها و زمین و کوه‌ها عرضه کردیم، پس، از حمل آن سر باز زدند و از آن هراسیدند.", "source": "سوره احزاب، آیه ۷۲"},
        {"text": "وَإِنْ كُنْتُمْ عَلَى سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُمْ بَعْضًا فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ أَمَانَتَهُ.", "translation": "و اگر در سفر بودید و نویسنده‌ای نیافتید، وثیقه‌ای گرفته شود؛ پس اگر به یکدیگر اطمینان داشتید، باید کسی که به او اطمینان شده امانت را بپردازد.", "source": "سوره بقره، آیه ۲۸۳"},
        {"text": "قَالَ اجْعَلْنِي عَلَى خَزَائِنِ الْأَرْضِ إِنِّي حَفِيظٌ عَلِيمٌ.", "translation": "[یوسف] گفت: مرا سرپرست خزاین این سرزمین قرار ده، چرا که من نگهبان و دانایم.", "source": "سوره یوسف، آیه ۵۵"},
        {"text": "وَمَا كَانَ لِنَبِيٍّ أَنْ يَغُلَّ وَمَنْ يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ الْقِيَامَةِ.", "translation": "و هیچ پیامبری را نسزد که خیانت ورزد [و در امانت غش کند]، و هر کس خیانت کند، روز قیامت با آنچه در آن خیانت کرده بیاید.", "source": "سوره آل عمران، آیه ۱۶۱"},
        {"text": "فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ.", "translation": "پس مرا یاد کنید تا شما را یاد کنم، و مرا سپاس گویید و کفران نعمت نکنید.", "source": "سوره بقره، آیه ۱۵۲"},
        {"text": "وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِنْ شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِنْ كَفَرْتُمْ إِنَّ عَذَابِي لَشَدِيدٌ.", "translation": "و آن‌گاه که پروردگارتان اعلام کرد که اگر واقعاً سپاسگزاری کنید، نعمت شما را افزون خواهم کرد و اگر ناسپاسی نمایید قطعاً عذاب من سخت خواهد بود.", "source": "سوره ابراهیم، آیه ۷"},
        {"text": "وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ وَمَنْ يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ.", "translation": "و همانا ما به لقمان حکمت دادیم که: خدا را سپاس بگوی؛ و هر کس سپاسگزاری کند، تنها به سود خود سپاس می‌گزارد.", "source": "سوره لقمان، آیه ۱۲"},
        {"text": "أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ.", "translation": "[سفارش کردیم] که برای من و برای پدر و مادرت سپاسگزاری کن، که بازگشت همگان به سوی من است.", "source": "سوره لقمان، آیه ۱۴"},
        {"text": "قَالَ هَذَا مِنْ فَضْلِ رَبِّي لِيَبْلُوَنِي أَأَشْكُرُ أَمْ أَكْفُرُ وَمَنْ شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ.", "translation": "[سلیمان] گفت: این از فضل پروردگار من است تا مرا بیازماید که آیا سپاسگزارم یا ناسپاس؛ و هر کس سپاسگزاری کند به سود خود سپاس می‌گزارد.", "source": "سوره نمل، آیه ۴۰"},
        {"text": "فَتَبَسَّمَ ضَاحِكًا مِنْ قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ.", "translation": "پس [سلیمان] از گفتار آن مورچه با تبسم بخندید و گفت: پروردگارا! به من الهام کن تا شکر نعمتی را که به من و پدر و مادرم ارزانی داشته‌ای به جای آورم.", "source": "سوره نمل، آیه ۱۹"},
        {"text": "وَإِنْ تَشْكُرُوا يَرْضَهُ لَكُمْ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى.", "translation": "و اگر سپاسگزاری کنید، آن را برای شما می‌پسندد؛ و هیچ باربرداری بار گناه دیگری را بر نمی‌دارد.", "source": "سوره زمر، آیه ۷"},
        {"text": "بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ.", "translation": "بلکه تنها خدا را بپرست و از سپاسگزاران باش.", "source": "سوره زمر، آیه ۶۶"},
        {"text": "وَاللَّهُ أَخْرَجَكُمْ مِنْ بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ لَعَلَّكُمْ تَشْكُرُونَ.", "translation": "و خداوند شما را از شکم مادرانتان بیرون آورد در حالی که چیزی نمی‌دانستید و برای شما گوش و چشم‌ها و دل‌ها قرار داد، باشد که سپاسگزاری کنید.", "source": "سوره نحل، آیه ۷۸"},
        {"text": "كُلُوا مِنْ رِزْقِ رَبِّكُمْ وَاشْكُرُوا لَهُ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ.", "translation": "از روزی پروردگارتان بخورید و او را سپاس گویید؛ شهری است پاکیزه و پروردگاری آمرزنده.", "source": "سوره سبا، آیه ۱۵"},
        {"text": "مَا يَفْعَلُ اللَّهُ بِعَذَابِكُمْ إِنْ شَكَرْتُمْ وَآمَنْتُمْ وَكَانَ اللَّهُ شَاكِرًا عَلِيمًا.", "translation": "اگر سپاسگزاری کنید و ایمان آورید، خدا را با عذاب شما چه کار؟ و خدا همواره حق‌شناس و داناست.", "source": "سوره نساء، آیه ۱۴۷"},
        {"text": "وَلَوْ أَنَّ أَهْلَ الْقُرَى آمَنُوا وَاتَّقَوْا لَفَتَحْنَا عَلَيْهِمْ بَرَكَاتٍ مِنَ السَّمَاءِ وَالْأَرْضِ.", "translation": "و اگر مردم شهرها ایمان می‌آوردند و تقوا پیشه می‌کردند، قطعاً برکاتی از آسمان و زمین را بر روی آنان می‌گشودیم.", "source": "سوره اعراف، آیه ۹۶"},
        {"text": "شَاكِرًا لِأَنْعُمِهِ اجْتَبَاهُ وَهَدَاهُ إِلَى صِرَاطٍ مُسْتَقِيمٍ.", "translation": "[ابراهیم] سپاسگزار نعمت‌های او بود؛ خدا او را برگزید و به راهی راست هدایتش کرد.", "source": "سوره نحل، آیه ۱۲۱"},
        {"text": "وَأَنْ لَيْسَ لِلْإِنْسَانِ إِلَّا مَا سَعَى.", "translation": "و اینکه برای انسان بهره‌ای جز آنچه تلاش کرده است نیست.", "source": "سوره نجم، آیه ۳۹"},
        {"text": "وَأَنَّ سَعْيَهُ سَوْفَ يُرَى.", "translation": "و اینکه تلاش و کوشش او به زودی دیده خواهد شد.", "source": "سوره نجم، آیه ۴۰"},
        {"text": "إِنَّ سَعْيَكُمْ لَشَتَّى.", "translation": "همانا تلاش و تکاپوی شما پراکنده و گوناگون است.", "source": "سوره لیل، آیه ۴"},
        {"text": "فَإِذَا قُضِيَتِ الصَّلَاةُ فَانْتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ.", "translation": "پس چون نماز پایان یافت، در زمین پراکنده شوید و از فضل و کرم خدا روزی بجویید.", "source": "سوره جمعه، آیه ۱۰"},
        {"text": "فَأَمَّا مَنْ أَعْطَى وَاتَّقَى * وَصَدَّقَ بِالْحُسْنَى * فَسَنُيَسِّرُهُ لِلْيُسْرَى.", "translation": "اما آن کس که بخشش نمود و پروا داشت، و پاداش نیکو را تصدیق کرد، به زودی راه آسانی را برای او هموار می‌سازیم.", "source": "سوره لیل، آیات ۵-۷"},
        {"text": "وَمَنْ أَرَادَ الْآخِرَةَ وَسَعَى لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُولَئِكَ كَانَ سَعْيُهُمْ مَشْكُورًا.", "translation": "و هر کس آخرت را بخواهد و برای آن تلاشی شایسته کند در حالی که مؤمن باشد، آنان کسانی هستند که تلاششان مورد قدردانی است.", "source": "سوره اسراء، آیه ۱۹"},
        {"text": "الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا.", "translation": "آنان کسانی هستند که تلاششان در زندگی دنیا به هدر رفته، در حالی که گمان می‌کنند کار نیک انجام می‌دهند.", "source": "سوره کهف، آیه ۱۰۴"},
        {"text": "وَجَعَلْنَا النَّهَارَ مَعَاشًا.", "translation": "و روز را مایه فعالیت و کسب معاش شما قرار دادیم.", "source": "سوره نبأ، آیه ۱۱"},
        {"text": "فَإِنَّ مَعَ الْعُسْرِ يُسْرًا * إِنَّ مَعَ الْعُسْرِ يُسْرًا * فَإِذَا فَرَغْتَ فَانْصَبْ.", "translation": "پس همانا با دشواری، آسانی است. آری، با دشواری، آسانی است. پس چون فارغ شدی به تلاش کوشا باش.", "source": "سوره انشراح، آیات ۵-۷"},
        {"text": "يَا أَيُّهَا الْإِنْسَانُ إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلَاقِيهِ.", "translation": "ای انسان! همانا تو با تلاش و رنج فراوان به سوی پروردگارت رهسپاری، پس او را ملاقات خواهی کرد.", "source": "سوره انشقاق، آیه ۶"},
        {"text": "لَقَدْ خَلَقْنَا الْإِنْسَانَ فِي كَبَدٍ.", "translation": "به راستی که ما انسان را در رنج و سختی آفریدیم [که با کار و تلاش عجین است].", "source": "سوره بلد، آیه ۴"},
        {"text": "وَآخَرُونَ يَضْرِبُونَ فِي الْأَرْضِ يَبْتَغُونَ مِنْ فَضْلِ اللَّهِ.", "translation": "و گروهی دیگر در زمین سفر می‌کنند و از فضل و روزی الهی می‌جویند.", "source": "سوره مزمل، آیه ۲۰"},
        {"text": "گندم از گندم بروید، جو ز جو.", "translation": "هر عملی نتیجه‌ای از جنس خودش دارد.", "source": "امثال و حکم دهخدا"},
        {"text": "تا نکاری، ندروی.", "translation": "بدون تلاش و کاشتن، نمی‌توانی نتیجه و محصولی به دست آوری.", "source": "امثال و حکم دهخدا"},
        {"text": "هر که درختی بنشاند، ثمرش را بچیند.", "translation": "نتیجه هر کار مفیدی سرانجام به انجام‌دهنده آن می‌رسد.", "source": "امثال و حکم دهخدا"},
        {"text": "زمین شخم‌زده، بذر را می‌طلبد.", "translation": "زمین آماده و مستعد، نیازمند همت برای شکوفایی است.", "source": "فرهنگ امثال فارسی"},
        {"text": "خاک زرخیز است اگر دهقان بکارد.", "translation": "ثروت و برکت در گرو تلاش و آبادانی است.", "source": "امثال و حکم دهخدا"},
        {"text": "روزی حلال، برکت دارد.", "translation": "درآمدی که از راه پاکیزه به دست آید همواره فزاینده است.", "source": "فرهنگ امثال فارسی"},
        {"text": "نان حلال، مایه آرامش جان است.", "translation": "کسب پاکیزه، باعث طمأنینه و آسودگی وجدان می‌گردد.", "source": "امثال و حکم دهخدا"},
        {"text": "مال حرام، وبال جان است.", "translation": "ثروتی که از راه ناحق کسب شود، مایه رنج و گرفتاری است.", "source": "امثال و حکم دهخدا"},
        {"text": "لقمه حلال، نور چشم است.", "translation": "غذای پاکیزه و حلال، موجب روشنی باطن و سلامت انسان می‌شود.", "source": "فرهنگ امثال فارسی"},
        {"text": "کار کردن عار نیست، بی‌کاری عار است.", "translation": "تلاش برای کسب روزی افتخار است و تن‌پروری مایه ننگ.", "source": "امثال و حکم دهخدا"},
        {"text": "حق‌دار، به حقش می‌رسد.", "translation": "حق هیچ‌گاه پایمال نمی‌شود و در نهایت به صاحبش بازمی‌گردد.", "source": "امثال و حکم دهخدا"},
        {"text": "چراغ ستمگر تا صبح نمی‌سوزد.", "translation": "پایه ظلم لرزان است و دوام نخواهد یافت.", "source": "امثال و حکم دهخدا"},
        {"text": "چوب خدا صدا ندارد، گر بخورد دوا ندارد.", "translation": "انتقام الهی برای پایمال کردن حقوق دیگران بی‌صدا اما قطعی است.", "source": "فرهنگ امثال فارسی"},
        {"text": "سوزن‌دزد، شتردزد می‌شود.", "translation": "تجاوز به حقوق کوچک دیگران، به ظلم‌های بزرگ‌تر می‌انجامد.", "source": "امثال و حکم دهخدا"},
        {"text": "مال مردم‌خور، روی رستگاری نبیند.", "translation": "غاصب حقوق دیگران هرگز در زندگی عاقبت‌به‌خیر نخواهد شد.", "source": "فرهنگ امثال فارسی"},
        {"text": "امانت را به خاک بسپار، به خائن مسپار.", "translation": "خاک از شخص خیانت‌کار در حفظ امانت مطمئن‌تر است.", "source": "امثال و حکم دهخدا"},
        {"text": "امانت‌دار، شریک مال مردم است.", "translation": "کسی که امین است، به واسطه اعتماد مردم در خیر آن‌ها شریک است.", "source": "فرهنگ امثال فارسی"},
        {"text": "خائن همیشه خائف است.", "translation": "شخص خیانت‌کار همیشه در ترس و دلهره به سر می‌برد.", "source": "امثال و حکم دهخدا"},
        {"text": "امین باش تا امان یابی.", "translation": "امانت‌داری سبب حفظ امنیت و آسایش خود شخص می‌شود.", "source": "فرهنگ امثال فارسی"},
        {"text": "گنج در ویرانه است و امانت در سینه مردان.", "translation": "همان‌گونه که گنج در جای امن نهفته است، امانت نیز در قلب انسان‌های بزرگ و مطمئن جای دارد.", "source": "امثال و حکم دهخدا"},
        {"text": "شکر نعمت، نعمتت افزون کند.", "translation": "سپاسگزاری باعث فزونی و برکت در دارایی‌ها می‌شود.", "source": "امثال و حکم دهخدا"},
        {"text": "کفر نعمت، از کفت بیرون کند.", "translation": "ناسپاسی باعث از دست رفتن داشته‌ها می‌شود.", "source": "فرهنگ امثال فارسی"},
        {"text": "برکت در حرکت است.", "translation": "فزونی روزی در گرو تلاش و جنب‌وجوش است.", "source": "امثال و حکم دهخدا"},
        {"text": "از تو حرکت، از خدا برکت.", "translation": "تلاش از سوی انسان است و افزونی و لطف از سوی خداوند.", "source": "امثال و حکم دهخدا"},
        {"text": "هر که شکر کند، فزونی یابد.", "translation": "انسان شاکر پیوسته در معرض الطاف بیشتر الهی است.", "source": "فرهنگ امثال فارسی"},
        {"text": "جوینده، یابنده است.", "translation": "هر کس برای هدفی تلاش کند، قطعاً به آن خواهد رسید.", "source": "امثال و حکم دهخدا"},
        {"text": "کار نیکو کردن از پر کردن است.", "translation": "مهارت و دستاورد بالا، نتیجه تمرین و ممارست فراوان است.", "source": "امثال و حکم دهخدا"},
        {"text": "قطره قطره جمع گردد، وانگهی دریا شود.", "translation": "تلاش‌های کوچک به مرور زمان دستاوردهای عظیمی خلق می‌کنند.", "source": "فرهنگ امثال فارسی"},
        {"text": "مزد دست، شیرین‌تر از عسل است.", "translation": "دسترنجی که با زحمت به دست آید، لذت‌بخش‌ترین دارایی است.", "source": "امثال و حکم دهخدا"},
        {"text": "گر صبر کنی ز غوره حلوا سازی.", "translation": "با تلاش و شکیبایی می‌توان از دشواری‌ها شیرینی و موفقیت ساخت.", "source": "فرهنگ امثال فارسی"},
        {"text": "مزرع سبز فلک دیدم و داس مه نو / یادم از کشته خویش آمد و هنگام درو", "translation": "دیدن جهان هستی باید انسان را به یاد نتیجه اعمال و زحمات خود بیندازد.", "source": "دیوان حافظ"},
        {"text": "درخت تو گر بار دانش بگیرد / به زیر آورد چرخ نیلوفری را", "translation": "اگر انسان با تلاش درخت وجود خود را پربار کند، جهان را به تسخیر درمی‌آورد.", "source": "دیوان ناصرخسرو"},
        {"text": "گندم از گندم بروید جو ز جو / از مکافات عمل غافل مشو", "translation": "هر چه در زمین هستی بکاری، همان را برداشت خواهی کرد.", "source": "مثنوی معنوی، مولوی"},
        {"text": "هر که نان از عمل خویش خورد / منت حاتم طائی نبرد", "translation": "کسی که روزی‌اش را با دسترنج حلال خود کسب کند، نیازمند بخشش دیگران نخواهد بود.", "source": "گلستان سعدی"},
        {"text": "به دست آهن‌تفته کردن خمیر / به از دست بر سینه پیش امیر", "translation": "تحمل سخت‌ترین کارها برای کسب حلال، بهتر از چاپلوسی نزد قدرتمندان است.", "source": "گلستان سعدی"},
        {"text": "میازار موری که دانه‌کش است / که جان دارد و جان شیرین خوش است", "translation": "هرگز به موجودات ضعیف ستم مکن، زیرا تجاوز به حقوق جانداران امری ناپسند است.", "source": "شاهنامه فردوسی"},
        {"text": "چنان با نیک و بد سر کن که بعد از مردنت عرفی / مسلمانت به زمزم شوید و هندو بسوزاند", "translation": "با تمام مردم چنان منصفانه و با رعایت حقوق رفتار کن که همه دوستدار تو باشند.", "source": "دیوان عرفی شیرازی"},
        {"text": "چو بد کردی مشو ایمن ز آفات / که واجب شد طبیعت را مکافات", "translation": "کسی که حقوق دیگران را ضایع کند، باید منتظر انتقام و مکافات جهان هستی باشد.", "source": "مخزن الاسرار نظامی"},
        {"text": "امانت نگه دار مردانه‌وار / که در روز محشر نگردی فکار", "translation": "با قدرت و صداقت امانت‌داری کن تا در پیشگاه خداوند شرمسار و مجروح نشوی.", "source": "بوستان سعدی"},
        {"text": "امانت‌داری آیین خرد است / که خائن در دو عالم دست‌رد است", "translation": "فرد خردمند همیشه امین است، زیرا خائن در دنیا و آخرت مردود و منفور است.", "source": "حديقة الحقيقة سنایی"},
        {"text": "شکر نعمت نعمتت افزون کند / کفر نعمت از کفت بیرون کند", "translation": "سپاسگزاری برکات را افزایش می‌دهد و ناسپاسی موجب از بین رفتن آن‌ها می‌شود.", "source": "مثنوی معنوی، مولوی"},
        {"text": "منت خدای را عز و جل که طاعتش موجب تقرب است و به شکر اندرش مزید نعمت", "translation": "ستایش مختص خداوندی است که فرمانبرداری از او باعث نزدیکی و سپاسش باعث فزونی نعمت است.", "source": "گلستان سعدی"},
        {"text": "از دست و زبان که برآید / کز عهده شکرش به درآید", "translation": "هیچ انسان و هیچ زبانی توانایی شکرگزاری کامل از نعمت‌های الهی را ندارد.", "source": "گلستان سعدی"},
        {"text": "نابرده رنج گنج میسر نمی‌شود / مزد آن گرفت جان برادر که کار کرد", "translation": "رسیدن به موفقیت و پاداش تنها در گرو تلاش و تحمل سختی‌هاست.", "source": "دیوان سعدی"},
